import java.util.*;

public class GameStages {

    public static int calculateMinimumTime(int N, int[] A, int[] B, int[] X) {
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[1]));
        int[] minTime = new int[N + 1];
        Arrays.fill(minTime, Integer.MAX_VALUE);
        minTime[1] = 0;
        pq.offer(new int[]{1, 0});

        while (!pq.isEmpty()) {
            int[] current = pq.poll();
            int stage = current[0];
            int time = current[1];

            if (stage == N) {
                return time;
            }

            if (stage + 1 <= N && time + A[stage - 1] < minTime[stage + 1]) {
                minTime[stage + 1] = time + A[stage - 1];
                pq.offer(new int[]{stage + 1, minTime[stage + 1]});
            }

            if (X[stage - 1] <= N && time + B[stage - 1] < minTime[X[stage - 1]]) {
                minTime[X[stage - 1]] = time + B[stage - 1];
                pq.offer(new int[]{X[stage - 1], minTime[X[stage - 1]]});
            }
        }

        return minTime[N];
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int N = in.nextInt();
        int[] A = new int[N - 1];
        int[] B = new int[N - 1];
        int[] X = new int[N - 1];

        for (int i = 0; i < N - 1; i++) {
            A[i] = in.nextInt();
            B[i] = in.nextInt();
            X[i] = in.nextInt();
        }

        System.out.println(calculateMinimumTime(N, A, B, X));
        in.close();
    }
}
